{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "ALB listener uses unencrypted HTTP",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener accepts traffic over HTTP on port 80, allowing data in transit between clients and the load balancer to be intercepted or modified."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "ALB listener does not enforce TLS 1.2 or later",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "Because the listener uses HTTP, it provides no TLS protection or minimum TLS version. An HTTPS listener with a modern security policy is required to enforce TLS 1.2 or later."
    }
  ],
  "patched_code": "variable \"webserver_certificate_arn\" {\n  description = \"ARN of the ACM certificate used by the webserver HTTPS listener\"\n  type        = string\n}\n\nresource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = 443\n  protocol          = \"HTTPS\"\n  certificate_arn   = var.webserver_certificate_arn\n  ssl_policy        = \"ELBSecurityPolicy-TLS13-1-2-2021-06\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}\n",
  "fix_summary": "Changed the listener from HTTP on port 80 to HTTPS on port 443 and configured a security policy that requires TLS 1.2 or later. Added a required variable for supplying the ACM certificate ARN without embedding certificate details in the file."
}
